public bool TryParseDate(ReadOnlySpan<char> timestamp, out DateOnly date)
{
    // Slicing a ReadOnlySpan<char> is allocation-free.
    var datePart = timestamp.Slice(0, 10);
    return DateOnly.TryParse(datePart, out date);
}

// Caller can pass a string, char[], or stack-allocated buffer.
TryParseDate("2026-09-26T13:00:00Z", out var d);

// Stack-only: fast, no allocations, cannot cross await
public int Sum(ReadOnlySpan<int> values)
{
    int total = 0;
    foreach (var v in values)
        total += v;
    return total;
}

// Async-safe: heap-backed, slightly more overhead
public async Task<int> SumAsync(Memory<int> values)
{
    await Task.Yield();
    return Sum(values.Span);
}
